import sys

def is_printable_ascii(b):
    return 0x20 <= b <= 0x7e

def extract_ascii_substrings(s, min_length=10):
    results = []
    current = []
    for b in s:
        if is_printable_ascii(b):
            current.append(chr(b))
        else:
            if len(current) >= min_length:
                results.append(''.join(current))
            current = []
    if len(current) >= min_length:
        results.append(''.join(current))
    return results

def main():
    if len(sys.argv) < 2:
        print(f"Usage: {sys.argv[0]} secret_bytes.bin")
        sys.exit(1)
    fname = sys.argv[1]
    with open(fname, "rb") as f:
        S = f.read()
    for offset in range(9):
        substr = S[offset:offset+64]
        if b'flag{' in substr and b'}' in substr:
            # Try to extract the flag using regex
            import re
            m = re.search(rb'flag\{[^}]+\}', substr)
            if m:
                print(f"Found flag at offset {offset}: {m.group(0).decode(errors='replace')}")
                return
        substrs = extract_ascii_substrings(substr, min_length=10)
        if substrs:
            print(f"Offset {offset}: Partially printable substrings:")
            for s in substrs:
                print(s)

if __name__ == "__main__":
    main()

