def parse_hex_string(hs):
    # remove whitespace and newlines, then decode
    hs = hs.replace("\n", "").replace(" ", "")
    return binascii.unhexlify(hs)


def is_printable(ch):
    # Accept flag format and typical printable ASCII
    return (ch >= 0x20 and ch <= 0x7e)


def extract_ascii_substrings(s, min_length=10):
    subs = []
    current = b""
    for b in s:
        if is_printable(b):
            current += bytes([b])
        else:
            if len(current) >= min_length:
                subs.append(current.decode("latin1"))
            current = b""
    if len(current) >= min_length:
        subs.append(current.decode("latin1"))
    return subs


def search_flag_in_string(secret_bytes):
    candidates = []
    for offset in range(9):
        substr = secret_bytes[offset:]
        ascii_candidates = extract_ascii_substrings(substr, min_length=10)
        for substr in ascii_candidates:
            if "flag{" in substr:
                print(f"[Possible flag found at offset {offset}]: {substr}")
                candidates.append(substr)
            else:
                print(f"[ASCII string at offset {offset}]: {substr}")
    return candidates


def main():
    secret = parse_hex_string(hex_string)
    candidates = search_flag_in_string(secret)
    if not candidates:
        print("No candidates of flag format found.")

if __name__ == "__main__":
    main()

